# /// script
# requires-python = ">=3.11"
# dependencies = []
# ///
"""Exclusion categories -> SDG targets/indicators crosswalk.

Subcommands:
  fetch   download the pinned sources into .cache/ and check them against MANIFEST.tsv
  build   write sdg-index.tsv, computed.tsv and gaps.tsv from the pinned sources,
          lexicon.tsv, proposed.tsv and the taxonomy
  verify  rebuild in memory and compare byte-for-byte with the committed files;
          check every span, every proposed quote and every manifest hash

Stdlib only. No clock, host or random value enters any output.
"""

from __future__ import annotations

import argparse
import hashlib
import json
import re
import sys
import urllib.request
import xml.etree.ElementTree as ET
import zipfile
from pathlib import Path

HERE = Path(__file__).resolve().parent
CACHE = HERE / ".cache"
TAXONOMY = HERE.parent.parent / "linked-data" / "taxonomy.json"
UA = "praxis-crosswalk/0.1"
CATEGORY_IRI = "https://ethicic.com/ns/exclusions/category/"
NS = {"m": "http://schemas.openxmlformats.org/spreadsheetml/2006/main"}

RELATIONS = {"harms", "relates"}
REVIEW_STATUSES = {"proposed", "approved", "rejected"}


# ---------------------------------------------------------------- helpers

def sha256_bytes(b: bytes) -> str:
    return hashlib.sha256(b).hexdigest()



# ---------------------------------------------------------------- sources

def manifest() -> dict[str, dict[str, str]]:
    _, _, rows = read_tsv(HERE / "MANIFEST.tsv")
    return {r["name"]: r for r in rows}


def source_path(row: dict[str, str]) -> Path:
    p = row["local_path"]
    return (HERE / p).resolve()


def check_manifest(errors: list[str]) -> None:
    for name, row in manifest().items():
        p = source_path(row)
        if not p.exists():
            errors.append(f"MANIFEST {name}: missing {row['local_path']} (run fetch)")
            continue
        b = p.read_bytes()
        if str(len(b)) != row["bytes"]:
            errors.append(f"MANIFEST {name}: bytes {len(b)} != {row['bytes']}")
        if sha256_bytes(b) != row["sha256"]:
            errors.append(f"MANIFEST {name}: sha256 mismatch")


def cmd_fetch(_: argparse.Namespace) -> int:
    errors: list[str] = []
    for name, row in manifest().items():
        if not row["url"].startswith("http"):
            continue
        p = source_path(row)
        p.parent.mkdir(parents=True, exist_ok=True)
        req = urllib.request.Request(row["url"], headers={"User-Agent": UA})
        with urllib.request.urlopen(req, timeout=60) as r:
            p.write_bytes(r.read())
        print(f"fetched {name} -> {row['local_path']}")
    check_manifest(errors)
    for e in errors:
        print("FAIL", e)
    return 1 if errors else 0


    return out, errors


def check_proposed(errors: list[str]) -> None:
    records, _ = framework()
    text = {r["code"]: r["text"] for r in records if r["level"] == "target"}
    cats = {c["sub_category_code"] for c in taxonomy()}
    seen = set()
    for i, p in enumerate(proposed(), start=2):
        where = f"proposed.tsv row {i} ({p['category']} {p['sdg_target']})"
        if p["category"] not in cats:
            errors.append(f"{where}: unknown category")
        if p["sdg_target"] not in text:
            errors.append(f"{where}: unknown target")
        elif len(p["target_quote"]) > WINDOW_MAX:
            errors.append(f"{where}: target_quote longer than {WINDOW_MAX}")
        elif p["target_quote"] not in text[p["sdg_target"]]:
            errors.append(f"{where}: target_quote is not verbatim in the pinned target text")
        if p["relation"] not in RELATIONS:
            errors.append(f"{where}: bad relation {p['relation']!r}")
        if p["review_status"] not in REVIEW_STATUSES:
            errors.append(f"{where}: bad review_status")
        if not p["witness"].startswith("llm:") or "prompt=" not in p["witness"]:
            errors.append(f"{where}: witness must name llm:<model> and prompt=")
        key = (p["category"], p["sdg_target"])
        if key in seen:
            errors.append(f"{where}: duplicate pair")
        seen.add(key)


def check_computed_spans(errors: list[str]) -> None:
    records, _ = framework()
    text = {r["code"]: r["text"] for r in records if r["level"] != "goal"}
    _, _, rows = read_tsv(HERE / "computed.tsv")
    for r in rows:
        where = f"computed {r['category']} {r['sdg_code']}"
        full = text.get(r["sdg_code"], "")
        s, e = int(r["span_start"]), int(r["span_end"])
        ws, we = int(r["window_start"]), int(r["window_end"])
        if sha256_text(full[s:e]) != r["span_sha256"]:
            errors.append(f"{where}: sentence span does not re-slice to its sha256")
        if not (s <= ws < we <= e) or full[ws:we] != r["window_text"]:
            errors.append(f"{where}: window does not re-slice inside its sentence")
        if len(r["window_text"]) > WINDOW_MAX:
            errors.append(f"{where}: window longer than {WINDOW_MAX}")
        if not term_regex(r["match_term"]).search(r["window_text"]):
            errors.append(f"{where}: term not in window")
        if r["direction"] != "unassessed":
            errors.append(f"{where}: direction must be 'unassessed'")


def cmd_build(_: argparse.Namespace) -> int:
    out, errors = build_outputs()
    for e in errors:
        print("FAIL", e)
    if errors:
        return 1
    for name, b in out.items():
        (HERE / name).write_bytes(b)
        print(f"wrote {name} {len(b)} bytes sha256={sha256_bytes(b)}")
    return 0


def cmd_verify(_: argparse.Namespace) -> int:
    out, errors = build_outputs()
    for name, b in out.items():
        p = HERE / name
        if not p.exists() or p.read_bytes() != b:
            errors.append(f"{name}: committed file differs from rebuild")
    if not errors:
        check_proposed(errors)
        check_computed_spans(errors)
    for e in errors:
        print("FAIL", e)
    if not errors:
        print("verify ok")
    return 1 if errors else 0


def main() -> int:
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    sub = ap.add_subparsers(dest="cmd", required=True)
    sub.add_parser("fetch").set_defaults(fn=cmd_fetch)
    sub.add_parser("build").set_defaults(fn=cmd_build)
    sub.add_parser("verify").set_defaults(fn=cmd_verify)
    a = ap.parse_args()
    return a.fn(a)


if __name__ == "__main__":
    sys.exit(main())
