# /// script
# requires-python = ">=3.11"
# dependencies = []
# ///
"""Build methods.tsv, uses.tsv and computed/ from the hand-written inputs and the pins.

    uv run scripts/build.py --epoch-csv PATH [--out DIR]

Run from resources/topologies/training-methods/. Standard library only. Reads
`methods.in.tsv`, `uses.in.tsv`, `MANIFEST.tsv` and the pinned bytes in
`.cache/`; reads the Epoch AI notable-models CSV from the path given (the
anthropic-pbc repository pins it at corpus/epoch/ai-models/). Writes
`methods.tsv`, `uses.tsv` and `computed/*.tsv` under --out (default: here).
No clock, host or random value enters any output, so two runs are
byte-identical. Exits 1 if the method tree is malformed, a pin's hash does not
match, or a row marked for quotation has a quote that is not in its pin.
"""
from __future__ import annotations

import argparse
import csv
import gzip
import hashlib
import html
import json
import re
import sys
from collections import Counter, defaultdict
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
CACHE = ROOT / ".cache"
WITNESS = "llm:claude-opus-5-5 prompt=unrecorded"
STAGES = ["pretraining", "mid-training", "supervised fine-tuning", "preference/RL", "distillation",
          "efficiency/compression", "safety/alignment", "evaluation", "data"]
# Hosts whose terms bar crawling, scraping or automated access: recorded, never fetched.

def write_tsv(path: Path, cols: list[str], rows: list[dict[str, str]]) -> None:
    def clean(v: object) -> str:
        return re.sub(r"[\t\r\n]+", " ", str(v))
    out = ["\t".join(cols)] + ["\t".join(clean(r.get(c, "")) for c in cols) for r in rows]
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text("\n".join(out) + "\n", encoding="utf-8")


# ---------------------------------------------------------------- pins

MANIFEST = {r["id"]: r for r in read_tsv(ROOT / "MANIFEST.tsv")}
_bytes: dict[str, bytes] = {}


def pin_bytes(pin_id: str) -> bytes | None:
    if pin_id in _bytes:
        return _bytes[pin_id]
    row = MANIFEST.get(pin_id)
    if row is None:
        return None
    hits = sorted(CACHE.glob(pin_id + ".*"))
    if not hits:
        problems.append(f"pin {pin_id} in MANIFEST but missing from .cache/")
        return None
    data = hits[0].read_bytes()
    if hashlib.sha256(data).hexdigest() != row["sha256"]:
        problems.append(f"pin {pin_id}: SHA-256 does not match MANIFEST")
        return None
    _bytes[pin_id] = data
    return data


def norm(s: str) -> str:
    return re.sub(r"\s+", " ", s).strip()


def arxiv_meta(axid: str) -> dict[str, str] | None:
    raw = pin_bytes("ax-" + axid)
    if raw is None:
        return None
    t = raw.decode("utf-8", "replace")
    meta = {}
    for k in ("title", "date", "arxiv_id", "abstract"):
        m = re.search(r'<meta name="citation_%s" content="([^"]*)"' % k, t)
        meta[k] = norm(html.unescape(m.group(1))) if m else ""
    return meta if meta["arxiv_id"] == axid else None


def openalex_refs() -> dict[str, dict]:
    out: dict[str, dict] = {}
    for pid in sorted(k for k in MANIFEST if k.startswith("oa-refs-")):
        raw = pin_bytes(pid)
        if raw is None:
            continue
        for w in json.loads(raw)["results"]:
            ids = {(w.get("doi") or "").lower().replace("https://doi.org/", "")}
