# /// script
# requires-python = ">=3.11"
# dependencies = ["blake3==1.0.11"]
# ///
"""The one fetch gate, pinner, extractor and verifier for every topology folder.

    uv run scripts/topo.py [--folder DIR] pin [--only ID,...] [--fetched DATE] [--dry-run]
    uv run scripts/topo.py [--folder DIR] terms [--only ID,...] [--fetched DATE] [--dry-run]
    uv run scripts/topo.py [--folder DIR] text ID
    uv run scripts/topo.py [--folder DIR] grep ID REGEX
    uv run scripts/topo.py [--folder DIR] verify
    uv run scripts/topo.py gate build|check|audit
    uv run scripts/topo.py gate decide URL [--terms]
    uv run scripts/topo.py [--folder DIR] links URL... | probe URL...

--folder is a topology folder (default: resources/topologies itself); the
per-folder `scripts/pin.py` files are thin wrappers that pass it. Every
producer that downloads anything (these folders and
crosswalks/exclusions-sdg/crosswalk.py) goes through `gated_fetch`, the only
function here that opens a network connection.

THE GATE. A URL is fetched only if the host's recorded terms verdict in
`resources/topologies/gate.tsv` permits it (open, redistribution-barred,
robots-conditional). A barred verdict (ai-barred, extraction-barred,
rule-barred) refuses the host permanently: nothing is fetched from it, terms
page and robots.txt included. A host with no verdict, or `unverified` or
`licence-required`, is refused, except for two requests: its robots.txt, and
a terms page declared as a `t-` row in targets.tsv (the `terms` step). Record
the verdict (bodies.tsv, a terms.tsv/sources.tsv verdict column, or
gate.in.tsv), run `gate build`, then `pin` the content. `gate.tsv` is
derived, never edited; `verify` fails when it is stale.

No clock enters any output: the fetch date is an argument. robots.txt is
honoured (401/403/5xx on robots.txt = disallow, RFC 9309); every fetch waits
max(1.5 s, the robots Crawl-delay). The User-Agent carries no personal
identifier. Bodies are capped at 20 MB.
"""
from __future__ import annotations

import argparse
import gzip
import hashlib
import html
import html.parser
import re
import subprocess
import sys
import time
import urllib.error
import urllib.parse
import urllib.request
import urllib.robotparser
from pathlib import Path

UA = "praxis-topologies/0.1"
CAP = 20 * 1024 * 1024
BASE = Path(__file__).resolve().parent.parent          # resources/topologies
GATE = BASE / "gate.tsv"
GATE_IN = BASE / "gate.in.tsv"
ROOT = BASE                                            # the folder being worked on
CACHE = BASE / ".topocache"
FETCHED = "2026-11-04"
MANIFEST_COLS = ["id", "body_id", "url", "bytes", "sha256", "blake3", "fetched", "note"]
MIN_DELAY = 1.5

# Per-folder settings: cache directory, default fetch date, quote tables to verify.
# A quote table row is checked byte-for-byte against the extracted text of its pin
# (or a local file under the folder), against its SHA-256, and against the quote cap.
QUOTE_TABLES: dict[str, list[dict[str, str]]] = {
    "ai-benefit-claims": [
        {"table": "claims.tsv", "id": "id", "ref": "manifest_id", "quote": "quote", "sha": "quote_sha256"},
        {"table": "author-positions.tsv", "id": "id", "ref": "manifest_id", "quote": "quote", "sha": "quote_sha256"},
        {"table": "cases.tsv", "id": "id", "ref": "primary_manifest_id", "quote": "primary_quote",
         "sha": "primary_quote_sha256", "status": "primary_quote_status"},
        {"table": "cases.tsv", "id": "id", "ref": "author_position_source", "ref_via": "sources.tsv:url",
         "quote": "author_position_quote", "sha": "author_position_quote_sha256", "suffix": "/author"},
    ],
}
FOLDERS: dict[str, dict] = {
    "topologies": {"cache": ".topocache", "fetched": "2026-11-04"},
    "ai-centers": {"cache": ".cache", "fetched": "2026-11-04"},
    "training-methods": {"cache": ".cache", "fetched": "2026-11-04"},
    "ai-benefit-claims": {"cache": ".cache", "fetched": "2026-11-05"},
}


def configure(folder: Path | str | None = None) -> None:
    """Point ROOT/CACHE/FETCHED at a topology folder (default: resources/topologies)."""
    global ROOT, CACHE, FETCHED
    ROOT = Path(folder).resolve() if folder else BASE
    name = "topologies" if ROOT == BASE else ROOT.name
    cfg = FOLDERS.get(name, {"cache": ".cache", "fetched": "2026-11-04"})
    CACHE = ROOT / cfg["cache"]
    FETCHED = cfg["fetched"]


# ---------------------------------------------------------------- tsv

def read_tsv(path: Path) -> list[dict[str, str]]:
    if not path.exists():
        return []
    lines = path.read_text(encoding="utf-8").splitlines()
    head = lines[0].split("\t")
    return [dict(zip(head, ln.split("\t"))) for ln in lines[1:] if ln.strip()]


def tsv_bytes(cols: list[str], rows: list[dict[str, str]]) -> bytes:
    out = ["\t".join(cols)] + ["\t".join(r.get(c, "") for c in cols) for r in rows]
    return ("\n".join(out) + "\n").encode("utf-8")


def write_tsv(path: Path, cols: list[str], rows: list[dict[str, str]]) -> None:
    path.write_bytes(tsv_bytes(cols, rows))


# ---------------------------------------------------------------- cache paths

JSON_HOSTS = {"api.openalex.org", "api.ror.org"}
JSON_PREFIXES = ("huggingface.co/api/", "www.wikidata.org/w/api.php")


def ext_for(url: str) -> str:
    p = urllib.parse.urlparse(url)
    if p.netloc in JSON_HOSTS or (p.netloc + p.path).startswith(JSON_PREFIXES):
        return ".json"
    if p.netloc == "arxiv.org" and p.path.startswith("/abs/"):
        return ".html"
    suffix = Path(p.path).suffix.lower()
    return suffix if re.fullmatch(r"\.[a-z0-9]{1,5}", suffix or "") else ".html"


def cache_path(pin_id: str, url: str) -> Path:
    return CACHE / f"{pin_id}{ext_for(url)}"


# ---------------------------------------------------------------- the gate

BARRED = {"rule-barred", "ai-barred", "extraction-barred"}
PERMITS = {"open", "redistribution-barred", "robots-conditional"}
REFUSES = {"licence-required", "unverified"}
VERDICTS = BARRED | PERMITS | REFUSES
# Most restrictive first; `unverified` only wins when nothing else is recorded.
RANK = ["rule-barred", "ai-barred", "extraction-barred", "licence-required",
        "redistribution-barred", "robots-conditional", "open", "unverified"]
# Hosts that serve many owners' files: a verdict recorded for one repository
# covers that repository's path, never the whole host.
SHARED_HOSTS = {"raw.githubusercontent.com", "github.com", "gist.githubusercontent.com",
                "huggingface.co", "s3.amazonaws.com"}
GATE_COLS = ["scope", "verdict", "fetch", "evidence"]


class GateRefused(Exception):
    pass


def _host(url: str) -> str:
    return urllib.parse.urlparse(url).netloc.lower()


def scope_of(url: str) -> str:
    p = urllib.parse.urlparse(url)
    host = p.netloc.lower()
    if host in SHARED_HOSTS:
        parts = [x for x in p.path.split("/") if x][:2]
        return host + "/" + "/".join(parts) + "/" if parts else host
    return host


def _verdict_token(v: str) -> str:
    tok = re.split(r"[\s;,(]", v.strip(), maxsplit=1)[0] if v.strip() else ""
    return tok if tok in VERDICTS else ""


def gate_records() -> list[tuple[str, str, str]]:
    """(scope, verdict, evidence) from every structured verdict record, plus gate.in.tsv."""
    recs: list[tuple[str, str, str]] = []

    def add(url: str, verdict: str, ev: str) -> None:
        url = url.strip().removeprefix("unverified:")
        if not url.startswith(("http://", "https://")) or not verdict:
            return
        recs.append((scope_of(url), verdict, ev))

    for r in read_tsv(BASE / "bodies.tsv"):
        v = _verdict_token(r.get("terms_verdict", ""))
        for col in ("terms_url", "artifact_url"):
            add(r.get(col, ""), v, f"bodies.tsv#{r['id']}={v}")
    for folder in sorted(p for p in BASE.iterdir() if p.is_dir() and (p / "MANIFEST.tsv").exists()):
        for r in read_tsv(folder / "terms.tsv"):
            if "verdict" in r:
                v = _verdict_token(r["verdict"])
                add(r["terms_url"], v, f"{folder.name}/terms.tsv#{r['body_id']}={v}")
        for r in read_tsv(folder / "sources.tsv"):
            v = _verdict_token(r.get("terms_verdict", r.get("verdict", "")))
            add(r.get("url", ""), v, f"{folder.name}/sources.tsv#{r['id']}={v}")
    for r in read_tsv(GATE_IN):
        v = _verdict_token(r["verdict"])
        if v:
            recs.append((r["scope"].lower(), v, f"gate.in.tsv#{r['scope']}={v}"))
    return recs


def gate_build_rows() -> list[dict[str, str]]:
    by: dict[str, set[tuple[str, str]]] = {}
    for scope, v, ev in gate_records():
        by.setdefault(scope, set()).add((v, ev))
    rows = []
    for scope in sorted(by):
        verdicts = {v for v, _ in by[scope]}
        verdict = min(verdicts, key=RANK.index)
        fetch = "barred" if verdict in BARRED else "permitted" if verdict in PERMITS else "refused"
        rows.append({"scope": scope, "verdict": verdict, "fetch": fetch,
                     "evidence": " ".join(sorted(ev for _, ev in by[scope]))})
    return rows


def load_gate(path: Path | None = None) -> list[dict[str, str]]:
    return read_tsv(path or GATE)


def _matching(url: str, gate: list[dict[str, str]]) -> list[dict[str, str]]:
    p = urllib.parse.urlparse(url)
    host = p.netloc.lower()
    hp = host + (p.path or "/")
    out = []
    for r in gate:
        s = r["scope"]
        if s.startswith("."):
            ok = host == s[1:] or host.endswith(s)
        elif "/" in s:
            ok = hp.startswith(s)
        else:
            ok = host == s
        if ok:
            out.append(r)
    return out


def gate_decision(url: str, purpose: str = "content",
                  gate: list[dict[str, str]] | None = None) -> tuple[bool, str, str]:
    """(allowed, verdict, reason). purpose: content | terms | robots."""
    gate = load_gate() if gate is None else gate
    p = urllib.parse.urlparse(url)
    if p.scheme not in ("http", "https") or not p.netloc:
        return False, "", "not an http(s) URL"
    rows = _matching(url, gate)
    barred = [r for r in rows if r["verdict"] in BARRED]
    if barred:
        r = min(barred, key=lambda r: RANK.index(r["verdict"]))
        return False, r["verdict"], f"host barred ({r['verdict']}, scope {r['scope']}): never fetched"
    if purpose == "robots":
        if p.path == "/robots.txt" and not p.query:
            return True, "", "robots.txt of a host that is not barred"
        return False, "", "robots purpose is only for /robots.txt"
    if purpose == "terms":
        return True, "", "declared terms page (t- row) of a host that is not barred"
    if not rows:
        return False, "", "no terms verdict recorded for this host: run the terms step and record one"
    best = max(rows, key=lambda r: len(r["scope"].lstrip(".")) + (1000 if not r["scope"].startswith(".") else 0))
    if best["verdict"] in PERMITS:
        return True, best["verdict"], f"verdict {best['verdict']} (scope {best['scope']})"
    return False, best["verdict"], f"verdict {best['verdict']} (scope {best['scope']}) does not permit fetching"


def quote_cap_bytes(url: str, gate: list[dict[str, str]] | None = None) -> int | None:
    """Licence cap on a committed quotation from this source, in UTF-8 bytes.

    Only an `open` verdict lifts the cap; every other source (no derivatives,
    no redistribution, unverified, barred) is quoted at most 300 bytes, the
    cap ai-benefit-claims set. A table may set a tighter cap of its own.
    """
    if not url.startswith(("http://", "https://")):
        return None  # a local file (e.g. the author's own dictation)
    rows = _matching(url, load_gate() if gate is None else gate)
    if rows and all(r["verdict"] == "open" for r in rows):
        return None
    return 300


def check_quote(quote: str, haystack: str, digest: str | None, cap: int | None) -> str:
    """'' if the quote is fine, else the problem."""
    if digest is not None and hashlib.sha256(quote.encode("utf-8")).hexdigest() != digest:
        return "QUOTE SHA MISMATCH"
    n = len(quote.encode("utf-8"))
    if cap is not None and n > cap:
        return f"QUOTE OVER CAP ({n} > {cap} bytes)"
    if quote not in haystack:
        return "QUOTE NOT IN PINNED TEXT"
    return ""


# ---------------------------------------------------------------- network (the only door)

_urlopen = urllib.request.urlopen
_sleep = time.sleep
_robots: dict[str, object] = {}
_delay: dict[str, float] = {}


def _http_get(url: str, limit: int = CAP) -> bytes:
    req = urllib.request.Request(url, headers={"User-Agent": UA, "Accept": "*/*"})
    with _urlopen(req, timeout=60) as r:
        data = r.read(limit + 1)
    if len(data) > limit:
        raise ValueError(f"over {limit} byte cap")
    return data


def robots_allows(url: str, gate: list[dict[str, str]] | None = None) -> tuple[bool, str]:
    p = urllib.parse.urlparse(url)
    base = f"{p.scheme}://{p.netloc}"
    if base not in _robots:
        ok, _, why = gate_decision(base + "/robots.txt", "robots", gate)
        if not ok:
            return False, why
        rp = urllib.robotparser.RobotFileParser()
        try:
            rp.parse(_http_get(base + "/robots.txt", 512 * 1024).decode("utf-8", "replace").splitlines())
            _robots[base] = rp
            cd = rp.crawl_delay(UA)
            _delay[p.netloc] = float(cd) if cd else 0.0
        except urllib.error.HTTPError as e:
            # 4xx: no robots file -> allowed; 401/403/5xx: disallowed (RFC 9309)
            _robots[base] = None if 400 <= e.code < 500 and e.code not in (401, 403) else "deny"
        except Exception:
            _robots[base] = None
    rp = _robots[base]
    if rp == "deny":
        return False, "robots.txt unreachable (auth/5xx)"
    if rp is None:
        return True, "no robots.txt"
    return rp.can_fetch(UA, url), "robots.txt"  # type: ignore[union-attr]


def gated_fetch(url: str, purpose: str = "content", gate: list[dict[str, str]] | None = None) -> bytes:
    """Fetch url only if the gate and robots.txt allow it. Raises GateRefused otherwise."""
    gate = load_gate() if gate is None else gate
    ok, _, why = gate_decision(url, purpose, gate)
    if not ok:
        raise GateRefused(why)
    rok, rwhy = robots_allows(url, gate)
    if not rok:
        raise GateRefused(f"disallowed by {rwhy}")
    try:
        data = _http_get(url)
    finally:
        _sleep(max(MIN_DELAY, _delay.get(_host(url), 0.0)))
    if not data:
        raise ValueError("empty body (likely a bot challenge)")
    return data


def fetch(url: str) -> bytes:
    """Back-compatible name: a content fetch through the gate."""
    return gated_fetch(url, "content")


# ---------------------------------------------------------------- pin

def purpose_of(pin_id: str) -> str:
    return "terms" if pin_id.startswith("t-") else "content"


def cmd_pin(args: argparse.Namespace) -> int:
    targets = read_tsv(ROOT / "targets.tsv")
    only = set(args.only.split(",")) if args.only else None
    manifest = {r["id"]: r for r in read_tsv(ROOT / "MANIFEST.tsv")}
    log = {r["id"]: r for r in read_tsv(CACHE / "fetchlog.tsv")}
    gate = load_gate()
    fetched = args.fetched or FETCHED
    for t in targets:
        if args.terms_only and not t["id"].startswith("t-"):
            continue
        if only is not None and t["id"] not in only:
            continue
        if only is None and t["id"] in manifest:
            continue
        purpose = purpose_of(t["id"])
        ok, _, why = gate_decision(t["url"], purpose, gate)
        if args.dry_run:
            print(f"{t['id']}\t{'WOULD-FETCH' if ok else 'REFUSED'}\t{purpose}\t{why}\t{t['url']}", flush=True)
            continue
        CACHE.mkdir(exist_ok=True)
        try:
            data = gated_fetch(t["url"], purpose, gate)
        except GateRefused as e:
            log[t["id"]] = {"id": t["id"], "url": t["url"], "outcome": f"refused: {e}"[:200]}
            print(f"{t['id']}\tREFUSED\t{e}", flush=True)
            save(manifest, log)
            continue
        except urllib.error.HTTPError as e:
            log[t["id"]] = {"id": t["id"], "url": t["url"], "outcome": f"HTTP {e.code}"}
            print(f"{t['id']}\tHTTP {e.code}", flush=True)
            continue
        except Exception as e:  # network, cap
            log[t["id"]] = {"id": t["id"], "url": t["url"], "outcome": f"error: {type(e).__name__}: {e}"[:200]}
            print(f"{t['id']}\tERR\t{e}", flush=True)
            continue
        cache_path(t["id"], t["url"]).write_bytes(data)
        manifest[t["id"]] = pin_row(t, data, fetched)
        log[t["id"]] = {"id": t["id"], "url": t["url"], "outcome": "pinned"}
        print(f"{t['id']}\tOK\t{len(data)}", flush=True)
        save(manifest, log)
    if not args.dry_run:
        save(manifest, log)
    return 0


def pin_row(t: dict[str, str], data: bytes, fetched: str) -> dict[str, str]:
    import blake3
    return {"id": t["id"], "body_id": t["body_id"], "url": t["url"], "bytes": str(len(data)),
            "sha256": hashlib.sha256(data).hexdigest(), "blake3": blake3.blake3(data).hexdigest(),
            "fetched": fetched, "note": t.get("note", "")}


def save(manifest: dict, log: dict) -> None:
    CACHE.mkdir(exist_ok=True)
    write_tsv(ROOT / "MANIFEST.tsv", MANIFEST_COLS, [manifest[k] for k in sorted(manifest)])
    write_tsv(CACHE / "fetchlog.tsv", ["id", "url", "outcome"], [log[k] for k in sorted(log)])


# ---------------------------------------------------------------- text extraction

class _Text(html.parser.HTMLParser):
    SKIP = {"script", "style", "noscript", "svg", "template", "head"}
    BLOCK = {"p", "div", "br", "li", "ul", "ol", "h1", "h2", "h3", "h4", "h5", "h6", "tr", "td",
             "th", "section", "article", "header", "footer", "nav", "table", "dd", "dt", "blockquote",
             "pre", "main", "aside", "hr", "title"}

    def __init__(self) -> None:
        super().__init__(convert_charrefs=True)
        self.parts: list[str] = []
        self.skip = 0

    def handle_starttag(self, tag, attrs):
        if tag in self.SKIP:
            self.skip += 1
        if tag in self.BLOCK:
            self.parts.append("\n")

    def handle_endtag(self, tag):
        if tag in self.SKIP and self.skip:
            self.skip -= 1
        if tag in self.BLOCK:
            self.parts.append("\n")

    def handle_data(self, data):
        if not self.skip:
            self.parts.append(data)


def extract(raw: bytes) -> str:
    """Deterministic HTML -> text: drop scripts/styles, one line per block, collapse spaces."""
    p = _Text()
    p.feed(raw.decode("utf-8", "replace"))
    p.close()
    lines = (re.sub(r"\s+", " ", ln).strip() for ln in "".join(p.parts).split("\n"))
    return "\n".join(ln for ln in lines if ln) + "\n"


def norm(s: str) -> str:
    return re.sub(r"\s+", " ", s).strip()


def extract_flat(raw: bytes) -> str:
    """One-line visible text of HTML (training-methods' quote haystack): drop
    script/style/noscript/svg/template/head, strip tags, unescape, collapse spaces."""
    t = raw.decode("utf-8", "replace")
    t = re.sub(r"(?is)<(script|style|noscript|svg|template|head)\b.*?</\1>", " ", t)
    return norm(html.unescape(re.sub(r"<[^>]+>", " ", t)))


def gunzip_if(raw: bytes) -> bytes:
    """Decompress a gzip body (servers send one unasked; some pins are .gz files).
    The pin and its hashes stay the bytes received."""
    return gzip.decompress(raw) if raw[:2] == b"\x1f\x8b" else raw


def text_of_bytes(raw: bytes, path: Path | None = None) -> str:
    raw = gunzip_if(raw)
    if raw[:5] == b"%PDF-":
        if path is None:
            raise ValueError("PDF extraction needs the file path")
        # Poppler pdftotext (not pinned by this script; its version is recorded in README).
        out = subprocess.run(["pdftotext", "-enc", "UTF-8", "-q", str(path), "-"],
                             capture_output=True, check=False).stdout.decode("utf-8", "replace")
        lines = (re.sub(r"\s+", " ", ln).strip() for ln in out.split("\n"))
        return "\n".join(ln for ln in lines if ln) + "\n"
    if raw.lstrip()[:1] == b"<":
        return extract(raw)
    return raw.decode("utf-8", "replace")


def pinned_text(pin_id: str) -> str:
    row = {r["id"]: r for r in read_tsv(ROOT / "MANIFEST.tsv")}[pin_id]
    path = cache_path(pin_id, row["url"])
    return text_of_bytes(path.read_bytes(), path)


def cmd_text(args: argparse.Namespace) -> int:
    sys.stdout.write(pinned_text(args.id))
    return 0


def cmd_grep(args: argparse.Namespace) -> int:
    rx = re.compile(args.regex, re.I)
    for n, ln in enumerate(pinned_text(args.id).splitlines(), 1):
        if rx.search(ln):
            print(f"{n}: {ln[: args.width]}")
    return 0


# ---------------------------------------------------------------- verify

def verify_quotes(gate: list[dict[str, str]]) -> tuple[int, list[str]]:
    specs = QUOTE_TABLES.get(ROOT.name if ROOT != BASE else "topologies", [])
    urls = {r["id"]: r["url"] for r in read_tsv(ROOT / "MANIFEST.tsv")}
    texts: dict[str, str] = {}
    problems: list[str] = []
    n = 0
    for s in specs:
        via = {}
        if "ref_via" in s:
            tab, col = s["ref_via"].split(":")
            via = {r["id"]: r[col] for r in read_tsv(ROOT / tab)}
        for r in read_tsv(ROOT / s["table"]):
            if "status" in s and r[s["status"]] != "verbatim":
                continue
            quote = r[s["quote"]]
            if "ref_via" in s and not quote:
                continue
            ref = via.get(r[s["ref"]], r[s["ref"]]) if via else r[s["ref"]]
            n += 1
            if ref not in texts:
                local = ROOT / ref
                texts[ref] = (local.read_text(encoding="utf-8") if "/" in ref and local.exists()
                              else pinned_text(ref))
            url = urls.get(ref, ref)
            bad = check_quote(quote, texts[ref], r[s["sha"]], quote_cap_bytes(url, gate))
            if bad:
                problems.append(f"{bad} {s['table']} {r[s['id']]}{s.get('suffix', '')} ({ref})")
    return n, problems


def cmd_verify(args: argparse.Namespace) -> int:
    import blake3
    bad = 0
    rows = read_tsv(ROOT / "MANIFEST.tsv")
    for r in rows:
        p = cache_path(r["id"], r["url"])
        if not p.exists():
            print(f"MISSING {r['id']} (re-fetch with: pin --only {r['id']})")
            bad += 1
            continue
        data = p.read_bytes()
        if (str(len(data)), hashlib.sha256(data).hexdigest(), blake3.blake3(data).hexdigest()) != (
                r["bytes"], r["sha256"], r["blake3"]):
            print(f"HASH MISMATCH {r['id']}")
            bad += 1
    terms = read_tsv(ROOT / "terms.tsv")
    for t in terms:
        if hashlib.sha256(t["clause"].encode("utf-8")).hexdigest() != t["clause_sha256"]:
            print(f"CLAUSE SHA MISMATCH {t['body_id']}")
            bad += 1
        if t["clause_status"] == "verbatim" and t["clause"] not in pinned_text(t["manifest_id"]):
            print(f"CLAUSE NOT IN PINNED TEXT {t['body_id']} ({t['manifest_id']})")
            bad += 1
    if GATE.read_bytes() != tsv_bytes(GATE_COLS, gate_build_rows()):
        print("GATE STALE: gate.tsv differs from `topo.py gate build`")
        bad += 1
    gate = load_gate()
    nq, qp = verify_quotes(gate)
    for p in qp:
        print(p)
    bad += len(qp)
    q = f", {nq} quotes" if nq else ""
    print(f"verify: {len(rows)} pins, {len(terms)} clauses{q}, {bad} problems")
    return 1 if bad else 0


# ---------------------------------------------------------------- gate commands

def cmd_gate(args: argparse.Namespace) -> int:
    if args.action == "build":
        b = tsv_bytes(GATE_COLS, gate_build_rows())
        GATE.write_bytes(b)
        print(f"wrote gate.tsv {len(b)} bytes sha256={hashlib.sha256(b).hexdigest()}")
        return 0
    if args.action == "check":
        ok = GATE.exists() and GATE.read_bytes() == tsv_bytes(GATE_COLS, gate_build_rows())
        print("gate ok" if ok else "GATE STALE: run `topo.py gate build`")
        return 0 if ok else 1
    if args.action == "decide":
        for url in args.urls:
            ok, v, why = gate_decision(url, "terms" if args.terms else "content")
            print(f"{'ALLOW' if ok else 'REFUSE'}\t{v or '-'}\t{why}\t{url}")
        return 0
    # audit: which existing pins would the gate refuse today? (report only)
    gate = load_gate()
    n = refused = 0
    for folder in [BASE] + sorted(p for p in BASE.iterdir() if p.is_dir() and (p / "MANIFEST.tsv").exists()):
        for r in read_tsv(folder / "MANIFEST.tsv"):
            n += 1
            ok, v, why = gate_decision(r["url"], purpose_of(r["id"]), gate)
            if not ok:
                refused += 1
                name = "." if folder == BASE else folder.name
                print(f"{name}\t{r['id']}\t{_host(r['url'])}\t{why}")
    print(f"audit: {n} pins, {refused} on hosts the gate would refuse today")
    return 0


# ---------------------------------------------------------------- discovery aids (gated)

def cmd_links(args: argparse.Namespace) -> int:
    """Discovery aid (writes nothing): list a page's links whose href or text names terms/licence."""
    rx = re.compile(args.regex, re.I)
    for url in args.urls:
        try:
            raw = gated_fetch(url, "terms" if args.terms else "content").decode("utf-8", "replace")
        except Exception as e:
            print(f"{url}\tREFUSED-OR-ERR\t{e}")
            continue
        seen = set()
        for m in re.finditer(r'<a\b[^>]*href="([^"]+)"[^>]*>(.*?)</a>', raw, re.I | re.S):
            href = urllib.parse.urljoin(url, m.group(1))
            text = re.sub(r"<[^>]+>|\s+", " ", m.group(2)).strip()[:60]
            if (rx.search(href) or rx.search(text)) and href not in seen:
                seen.add(href)
                print(f"{url}\t{href}\t{text}")
    return 0


def cmd_probe(args: argparse.Namespace) -> int:
    """Gate verdict, robots verdict, HTTP outcome, up to 3 terms-like links. Gated like
    everything else: a host with no permitting verdict is reported, not fetched."""
    rx = re.compile(r"terms|legal|copyright|licen[cs]e|conditions|disclaimer", re.I)
    for url in args.urls:
        try:
            raw = gated_fetch(url, "content").decode("utf-8", "replace")
        except GateRefused as e:
            print(f"{url}\tREFUSED\t{e}", flush=True)
            continue
        except urllib.error.HTTPError as e:
            print(f"{url}\tHTTP {e.code}", flush=True)
            continue
        except Exception as e:
            print(f"{url}\tERR {type(e).__name__}", flush=True)
            continue
        links: list[str] = []
        for m in re.finditer(r'<a\b[^>]*href="([^"]+)"', raw, re.I):
            href = urllib.parse.urljoin(url, m.group(1))
            if rx.search(href) and href not in links and not re.search(r"privacy|cookie", href, re.I):
                links.append(href)
        print(f"{url}\tOK\t{' '.join(links[:3])}", flush=True)
    return 0


# ---------------------------------------------------------------- cli

def main(argv: list[str] | None = None, folder: Path | str | None = None) -> int:
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--folder", default=None, help="topology folder (default: resources/topologies)")
    sub = ap.add_subparsers(dest="cmd", required=True)
    for name, terms_only in (("pin", False), ("terms", True)):
        p = sub.add_parser(name)
        p.add_argument("--only")
        p.add_argument("--fetched", default=None, help="fetch date recorded in MANIFEST (folder default)")
        p.add_argument("--dry-run", action="store_true", help="report gate decisions; no network, no writes")
        p.set_defaults(fn=cmd_pin, terms_only=terms_only)
    p = sub.add_parser("text"); p.add_argument("id"); p.set_defaults(fn=cmd_text)
    p = sub.add_parser("grep"); p.add_argument("id"); p.add_argument("regex")
    p.add_argument("--width", type=int, default=500); p.set_defaults(fn=cmd_grep)
    p = sub.add_parser("verify"); p.set_defaults(fn=cmd_verify)
    p = sub.add_parser("gate"); p.add_argument("action", choices=["build", "check", "audit", "decide"])
    p.add_argument("urls", nargs="*"); p.add_argument("--terms", action="store_true")
    p.set_defaults(fn=cmd_gate)
    p = sub.add_parser("links"); p.add_argument("urls", nargs="+"); p.add_argument("--terms", action="store_true")
    p.add_argument("--regex", default=r"terms|legal|copyright|licen[cs]e|conditions|disclaimer")
    p.set_defaults(fn=cmd_links)
    p = sub.add_parser("probe"); p.add_argument("urls", nargs="+"); p.set_defaults(fn=cmd_probe)
    a = ap.parse_args(argv)
    configure(a.folder or folder)
    return a.fn(a)


if __name__ == "__main__":
    raise SystemExit(main())

